#! /usr/bin/env python # -*- coding: utf-8 -*-
# Niniejsze dane stanowią tajemnicę przedsiębiorstwa. # The contents of this file is proprietary information.
import sys import os import time import calendar import http.client import urllib.request, urllib.error, urllib.parse import urllib.parse import base64 import suds import suds.client import json
from datetime import datetime
config = {"wsdlUrl": ["http://localhost:43080/eds.wsdl"], "httpUrl": ["http://localhost:43080"]} #config = {"wsdlUrl": ["http://192.168.50.51:43080/eds.wsdl"], # "httpUrl": ["http://192.168.50.51:43080"]} client = None
class ParamRequiredError(RuntimeError): pass
def param(name, *args, **kwargs): if name not in config: if len(args): return args[0] if 'default' in kwargs: return kwargs['default'] raise ParamRequiredError(name) return config[name][0]
def create_time_period(prefix="", no=0): period = client.factory.create("TimePeriod") if prefix + "from" in config and len(config[prefix + "from"]) > no and \ prefix + "till" in config and len(config[prefix + "till"]) > no: period.__dict__["from"] = create_timestamp(config[prefix + "from"][no]) period.__dict__["till"] = create_timestamp(config[prefix + "till"][no]) else: period.__dict__["from"].second = int(time.time()) - 3600 period.__dict__["till"].second = int(time.time()) return period
def create_timestamp(date_str): ts = client.factory.create("Timestamp") ts.second = calendar.timegm(time.strptime(date_str, "%Y-%m-%dT%H:%M:%S")) return ts
def create_struct(name, prefix="", no=0): struct = client.factory.create(name) for key in struct.__dict__: if prefix + key in config: struct.__dict__[key] = config[prefix + key][no] return struct
def wait_for_request_execution(req_id): st = time.time() while True: status = client.service.getRequestStatus(param('authString'), req_id) if status.status == "REQUEST-FAILURE": raise RuntimeError('Request failed: ' + str(status)) elif status.status == "REQUEST-SUCCESS": break elif status.status == "REQUEST-EXECUTING": sys.stderr.write("%3.0f%%\n" % float(status.progress)) time.sleep(0.5) #print('Request executed in: %d s' % int(time.time() - st + 0.5))
def getServerTime(): return client.service.getServerTime(param('authString'))
def login(): return client.service.login(param('user'), param('password'))
def ping(): return client.service.ping(param('authString'))
def logout(): return client.service.logout(param('authString'))
def getSecurityGroups(): return client.service.getSecurityGroups(param('authString'))
def getUserSecurityGroups(): return client.service.getUserSecurityGroups(param('authString'))
def getTechnologicalGroups(): return client.service.getTechnologicalGroups(param('authString'))
def getServerTime(): return client.service.getServerTime(param('authString'))
def getServerStatus(): return client.service.getServerStatus(param('authString'))
def getLicenseInfo(): return client.service.getLicenseInfo(param('authString'))
def getPoints(): return client.service.getPoints(param('authString'), create_struct("PointFilter"), param('order', None), param('startIdx', None), param('maxCount', None))
def getPointsWithCustomFilter(): return client.service.getPointsWithCustomFilter(param('authString'), param('source'), param("pointFilterName"), param('order', None), param('startIdx', None), param('maxCount', None))
def getPointsSources(): return client.service.getPointsSources(param('authString'))
def getModifiedPoints(): timestamp = create_struct("Timestamp") return client.service.getModifiedPoints(param('authString'), param('startIdx', None), param('maxCount', None), timestamp, param('dbSequence', None))
def operatePoints(): point = client.factory.create("PointNewValue") point.id = create_struct("PointId") point.value = create_struct("PointValue") point.quality = param('quality', None) return client.service.operatePoints(param('authString'), [point])
def publishPoints(): point = client.factory.create("PointNewValue") point.id = create_struct("PointId") point.value = create_struct("PointValue") point.quality = param('quality', None) point.duration.seconds = param('duration', None) points = client.factory.create("PointsNewValues") points.point = [point] return client.service.publishPoints(param('authString'), points)
def unpublishPoints(): pointid = create_struct("PointId") return client.service.unpublishPoints(param('authString'), pointid)
def getTrend(): request = create_struct("TrendRequest") request.period = create_time_period() request.pixelCount = param('pixelCount', 100) requestItem = create_struct("TrendRequestItem") requestItem.pointId = create_struct("PointId") del requestItem.shadePriority request.items.append(requestItem) req_id = client.service.requestTrend(param('authString'), request) wait_for_request_execution(req_id) return client.service.getTrend(param('authString'), req_id)
def getTrendGroups(): response = client.service.getTrendGroups(param('authString'), param('configurationVersion', None)) file_name = 'trend_groups-{}.json'.format(int(time.time() + 0.5))
with open(file_name, "wb") as f: f.write(response)
sys.stderr.write( "Trend groups saved to `{}` file ({:n}B).\n".format(file_name, len(response)))
def getTabular(): request = client.factory.create("TabularRequest") request.period = create_time_period() request.step.seconds = param('step', 60) requestItem = create_struct("TabularRequestItem") requestItem.pointId = create_struct("PointId") del requestItem.shadePriority if "param" in config: for val in config["param"].values(): requestItem.param.append(val)
request.items.append(requestItem) req_id = client.service.requestTabular(param('authString'), request) wait_for_request_execution(req_id) return client.service.getTabular(param('authString'), req_id)
def getTabularCSV(): request = client.factory.create("TabularRequest") request.period = create_time_period() request.step.seconds = param('step', 60) req_function = config['function']
points = config['point']
for point_name in points: requestItem = create_struct("TabularRequestItem") requestItem.pointId = create_struct("PointId") requestItem.pointId.iess = point_name del requestItem.shadePriority if "param" in config: for val in config["param"].values(): requestItem.param.append(val)
requestItem.function = req_function request.items.append(requestItem)
req_id = client.service.requestTabular(param('authString'), request) wait_for_request_execution(req_id) result = client.service.getTabular(param('authString'), req_id) header_items = ["time"] for pt_data in result.pointsIds: #print(f"{pt_data.iess}") header_items.append(f"{pt_data.iess}:{req_function}") print(",".join(header_items)) for row in result.rows: row_items = [f"{row.ts.second}"] for value in row.values: row_items.append(f"{value.value.dav}") print(",".join(row_items)) return #return result
def getShade(): request = client.factory.create("ShadeSelector") request.pointId = create_struct("PointId") request.period = create_time_period() req_id = client.service.requestShadesRead(param('authString'), [request]) wait_for_request_execution(req_id) return client.service.getShades(param('authString'), req_id)
def writeShade(): shades = [] shade = client.factory.create("Shade") shade.pointId = create_struct("PointId") shadeValue = create_struct("ShadeValue") shadeValue.period = create_time_period() shadeValue.value = create_struct("PointValue") shade.values.append(shadeValue) shades.append(shade) req_id = client.service.requestShadesWrite(param('authString'), shades) wait_for_request_execution(req_id)
def clearShade(): request = client.factory.create("ShadesClearRequest") item = client.factory.create("ShadesClearRequestItem") item.pointId = create_struct("PointId") item.period = create_time_period() request.item.append(item) req_id = client.service.requestShadesClear(param('authString'), request) wait_for_request_execution(req_id)
def copyShade(): request = client.factory.create("ShadesCopyRequest") item = client.factory.create("ShadesCopyRequestItem") item.srcPointId = create_struct("PointId", "src.") item.dstPointId = create_struct("PointId", "dst.") item.period = create_time_period() request.item.append(item) req_id = client.service.requestShadesCopy(param('authString'), request) wait_for_request_execution(req_id)
