url = client.service.openDiagram( param('authString'), param('source'), param('file'), refr, param('previousUrl', default=''), param('pointGroup', default=''), param('httpUrl', default='')) sys.stderr.write(url + '\n') if "width" in config and "height" in config: resolution = create_struct("DiagramResolution") client.service.resizeDiagram( param('authString'), url, "DIAGRAM-ROLE-MAIN", resolution)
features = client.service.getGfxSrvFeatures(param('authString'), url) sys.stderr.write("GfxSrv features: " + str(features) + "\n")
viewport = client.factory.create("DiagramArea") viewport.topLeft.x = 0 viewport.topLeft.y = 0 viewport.bottomRight.x = 1 viewport.bottomRight.y = 1
orgUrl = url url = urllib.parse.urlparse(url)
prettyPrintMetadata = param('prettyMeta', None)
client.service.setDiagramViewport( param('authString'), orgUrl, "DIAGRAM-ROLE-MAIN", viewport)
time.sleep(0.2)
tag = '0'
print((str(datetime.now()) + ': First diagram request!'))
try: while True: connection = http.client.HTTPConnection(url.hostname, url.port) connection.request("GET", url.path + "tag?_=" + str(int(time.time() + 0.5))) current_tag = connection.getresponse().read()
if current_tag == tag: continue tag = current_tag
print((str(datetime.now()) + ': new diagram tag = ' + tag))
connection.request("GET", url.path + "meta.json?tag=" + tag) metas = connection.getresponse().read() meta = json.loads(metas)
file_name = '{}{}-meta.json'.format(param('file'), int(time.time() + 0.5)) with open(file_name, "wb") as f: if prettyPrintMetadata: json.dump(meta, f, indent=2, separators=(',', ': ')) else: f.write(metas) sys.stderr.write( "Diagram meta data saved to `" + file_name + "` file.\n")
available_diagrams = []
def getRoleIdFileName(role, data, enforced_id=None): return (role, enforced_id if enforced_id is not None else data.get( 'id', ""), data.get('fileName', None))
if 'main' in meta and meta['main']: available_diagrams.append( getRoleIdFileName( 'main', meta['main'])) if 'subwindow' in meta and meta['subwindow']: available_diagrams.append( getRoleIdFileName( 'subwindow', meta['subwindow'])) if 'window' in meta and meta['window']: available_diagrams.append( getRoleIdFileName( 'window', meta['window'], enforced_id="")) available_diagrams.append( getRoleIdFileName( 'window', meta['window']))
for extraWindow in meta.get('extraWindows', []): available_diagrams.append( getRoleIdFileName( 'window', extraWindow))
for role_id_diagram in available_diagrams: request_url = '{}{}{}.png?tag={}'.format( url.path, role_id_diagram[0], role_id_diagram[1], tag) connection.request("GET", request_url) response = connection.getresponse()
if response.status != http.client.OK: if response.status == http.client.SEE_OTHER: sys.stderr.write("Tag {} is outdated, gfx_srv no longer has {}{}.png for this tag.\n" .format(tag, role_id_diagram[0], role_id_diagram[1])) sys.stderr.write("Got response '{} {}' for {}{}.png. Skipping other images.\n" .format(response.status, response.reason, role_id_diagram[0], role_id_diagram[1])) break
file_name = '{}{}-{}-{}{}.png'.format(param('file'), int(time.time() + 0.5), role_id_diagram[2], role_id_diagram[0], role_id_diagram[1])
body = response.read() with open(file_name, "wb") as f: f.write(body) sys.stderr.write( "Diagram view saved to `{}` file ({:n}B).\n".format( file_name, len(body)))
time.sleep(1)
except KeyboardInterrupt: client.service.closeDiagram(param('authString'), orgUrl)
