    def _wait_for_request_execution(self, req_id, get_chunks=None):
        progress = 0
        st = time.time()
        while True:
            time.sleep(0.2)
            res = self.session.get(self.api + 'requests?id=' + str(req_id), verify=self.verify)
            if not self._noRequestExecutionLogs:
                log_request(res, verbose=False, cookies=False, pretty_print=False)
            status = res.json()[str(req_id)]
            if status['status'] == 'FAILURE':
                raise RuntimeError('Request failed: ' + status['message'])
            elif status['status'] == 'SUCCESS':
                if get_chunks:
                    res = get_chunks()
                    log_request(res, floatPrecision=self._floatPrecision)
                break
            elif status['status'] == 'EXECUTING':
                if get_chunks and status['progress'] != progress:
                    res = get_chunks()
                    if not self._noRequestExecutionLogs:
                        log_request(res)
        print('req_id = {}, executed in: {:.3f} s\n'.format(req_id, time.time() - st))

    def _is_expected_result(self, res):
        expectedMatchCount = self.args.expectedMatchCount
        if expectedMatchCount is None:
            return True

        if res is None or not res.text:
            return True

        json_data = {}
        try:
            json_data = res.json()
        except requests.JSONDecodeError:
            print("Couldn’t decode the text into json")

        if 'matchCount' not in json_data.keys():
            return True

        return expectedMatchCount == json_data['matchCount']


def merge(dict1, dict2):
    return dict(list(dict1.items()) + list(dict2.items()))  # python 2 compatible syntax

def getSortedStringFromDictionary(dictionary):
     return ('{' + ', '.join("'" + k + "': '" + v + "'" for k, v in
         sorted(dictionary.items(), key=lambda x: x[0], reverse=False)) + '}')

def print_json_pretty(inputJson, floatPrecisionCall=None):
    return json.dumps(json.loads(inputJson, object_pairs_hook=OrderedDict, parse_float=floatPrecisionCall),
                      ensure_ascii=False,
                      indent=4,
                      separators=(',', ': '),
                      sort_keys=True)

def log_request(res, verbose=True, cookies=True, pretty_print=True, floatPrecision=None):
    floatPrecisionCall = None
    if floatPrecision:
        floatPrecisionCall = lambda numf: round(float(numf), floatPrecision)

    print('<<< Request: {} {}'.format(res.request.method, res.url))
    if verbose:
        headers = res.request.headers
        headers.pop('User-Agent')
        print('    [headers]: ' + getSortedStringFromDictionary(headers))
    if res.request.body:
        if pretty_print:
            print('    [body]: \n' + print_json_pretty(res.request.body, floatPrecisionCall))
        else:
            print('    [body]: ' + str(res.request.body.decode('utf-8')))
    print('>>> Response: ' + str(res.status_code))
    if verbose:
        print('    [headers]: ' + getSortedStringFromDictionary(headers))
    if cookies and res.cookies:
        print('    [cookies]: ' + str(res.cookies.get_dict()))
    if res.headers.get('content-type', '').startswith('application/json') and pretty_print:
        print('    [body]: \n' + print_json_pretty(res.content, floatPrecisionCall))
    elif res.content:
        print('    [body]: ' + res.content.decode('utf-8'))
    print('')


def read_extra_params(extra_args):
    params = {}
    for extra in extra_args:
        if '=' not in extra:
            print('Invalid argument: %s' % extra)
            exit(-1)
        name, val = extra.split('=', 1)
        if name in ['from', 'till']:
                val = str(calendar.timegm(time.strptime(val, "%Y-%m-%dT%H:%M:%S")))
        if name in params:
            if type(params[name]) == list:
                params[name].append(read_value(val))
            else:
                params[name] = [params[name], read_value(val)]
        elif val.startswith('[') and val.endswith(']'):
            params[name] = [read_value(v) for v in val[1:-1].split(',')]
            v = [read_value(v) for v in val[1:-1].split(',')]
        elif val.startswith("json:"):
            json_data = json.loads(val[5:])
            params[name] = json_data
        else:
            params[name] = read_value(val)
    return params


def read_value(val):
    if val.startswith('"') and val.endswith('"'):
        return val[1:-1]
    if val=="false" or val=="False":
        return False
    if val=="true" or val=="True":
        return True
    if val.isdigit():
        return int(val)
    try:
        float_val = float(val)
        return float_val if math.isfinite(float_val) else val
    except ValueError:
        return val


def get_time_shift_value(time_str):
    if time_str == "CURRENT_TIME":
        return 0

    m = re.match("CURRENT_TIME([-+][0-9]+)", time_str)
    if m:
        return int(m.group(1))

    print ("Invalid CURRENT_TIME format")


def is_valid_response(response):
    if response.status_code == 500:
        return False

    jsonData = {}
    if response.text:
        try:
            jsonData = json.loads(response.text)
        except json.decoder.JSONDecodeError:
            pass

    errorCode = 0
    errorMessage = None
    if isinstance(jsonData, dict):
        errorCode = jsonData.get('error', 0)
        errorMessage = jsonData.get('message', None)

    if (errorCode == 30 and errorMessage == "Points\' data not synchronized yet.") or \
       (errorCode == 31 and errorMessage == "Point not found"):
        return False
    return True


if __name__ == '__main__':
    args, extra_args = parser.parse_known_args()
    params = read_extra_params(extra_args)
    client = Client(args, params)

    if args.sessionid or args.endpoint.startswith('/') or args.endpoint in ('test', 'login', 'authenticate'):
        client.run(args.endpoint)
    else:
        client.run('login', verbose=False)
        client.run(args.endpoint)
        client.run('logout', verbose=False)

import numpy as np import pandas as pd import warnings
def _get_sample_intervals_mod( times: pd.DatetimeIndex, win_length: int ) -> [float, int]:
deltas = np.diff(times.values) / np.timedelta64(1, "m")
if len(deltas) == 0: raise ValueError("DatetimeIndex must contain at least two timestamps.")
sample_interval = float(np.median(deltas))
if np.any(np.abs(deltas - sample_interval) > 1e-6): warnings.warn( "Non-uniform time intervals detected. Using median interval " f"{sample_interval:.4f} minutes for calculations.", UserWarning )
samples_per_window = int(round(win_length / sample_interval))
return sample_interval, samples_per_window

import pandas as pd


def check_if_any_column_is_missing(
        df: pd.DataFrame,
        sensor_name: str,
        time_col: str,
        if_sunny_col: str = None
) -> None:
    """
    Checks if any column is missing from the dataframe.
    """

    if if_sunny_col is not None:
        required_cols = {time_col, if_sunny_col, sensor_name}
    else:
        required_cols = {time_col, sensor_name}

    missing = required_cols - set(df.columns)

    if missing:
        raise ValueError(f"DataFrame missing required columns: {missing}")

def _validate_tree_structure(node: dict) -> None:
    if "value" in node:
        return  # it's a leaf, that's fine

    required_keys = ["feature", "threshold", "left", "right"]
    for key in required_keys:
        if key not in node:
            raise ValueError(f"Missing key '{key}' in internal node: {node}")

    # Recursively validate children
    _validate_tree_structure(node["left"])
    _validate_tree_structure(node["right"])


def _traverse_tree(node: dict, x_val: float) -> float:
    if "value" in node:
        return node["value"]

    threshold = node["threshold"]
    feature = node["feature"]  # always 0 in this case

    if x_val <= threshold:
        return _traverse_tree(node["left"], x_val)
    else:
        return _traverse_tree(node["right"], x_val)

import numpy as np
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score
class SensorCalibrationMetrics: """ The class stores following metrics to evaluate model quality:
* ``MAE``: Mean Absolute Error - does not indicate whether the model overestimates or underestimates values * ``MSE``: Mean Squeared Error - is particularly sensitive to large errors * ``RMSE``: Root Mean Squared Erorr - same units as the predicted values * ``R2``: correlation between two datasets * ``MAPE``: Mean Absolute Percentage Error - especially useful when you want to assess the accuracy of predictions in percentage * ``Bias``: shows whether the model regularly over - or under-predicts """
def __init__(self, y_true: np.ndarray, y_pred:np.ndarray): self.y_true: np.ndarray = np.array(y_true) self.y_pred: np.ndarray = np.array(y_pred)
self.mae: float = mean_absolute_error(self.y_true, self.y_pred) self.mse: float = mean_squared_error(self.y_true, self.y_pred) self.rmse: float = np.sqrt(mean_squared_error(self.y_true, self.y_pred)) self.r2: float = r2_score(self.y_true, self.y_pred) self.mape: float = float(np.mean(np.abs((self.y_true - self.y_pred) / (self.y_true + 1e-8))) * 100) # +1e-8 for safety self.max_error: float = float(np.max(np.abs(self.y_true - self.y_pred))) self.bias: float = float(np.mean(self.y_pred - self.y_true))

