def load_and_merge_calibrated_data_from_each_sensor(
        df: pd.DataFrame,
        sensor_names: list[str],
        calibration_directory: Path,
        sensor_name_ref: Optional[str] = None
) -> pd.DataFrame:

    df = df.copy().reset_index(drop=True)

    merged_df = pd.DataFrame()

    for s_name in sensor_names:
        sanitized_name = sanitize_filename(s_name)
        csv_path = calibration_directory / f"{sanitized_name}_all_predicted.csv"

        if not csv_path.exists():
            raise FileNotFoundError(f"[ERROR] File not found: {csv_path}")

        tmp_df = pd.read_csv(csv_path)

        if "y_pred" not in tmp_df.columns or "time" not in tmp_df.columns:
            raise KeyError(f"[ERROR] File {csv_path} must contain 'y_pred' and 'time' columns")

        tmp_df["time"] = pd.to_datetime(tmp_df["time"])
        tmp_df.rename(columns={"y_pred": sanitized_name}, inplace=True)

        if merged_df.empty:
            merged_df = tmp_df[["time", sanitized_name]]
        else:
            merged_df = pd.merge(merged_df, tmp_df[["time", sanitized_name]], on="time", how="outer")

    if sensor_name_ref is not None:
        sanitized_ref = sanitize_filename(sensor_name_ref)
        if sensor_name_ref not in df.columns:
            raise KeyError(f"[ERROR] Reference sensor '{sensor_name_ref}' not found in original dataframe")
        merged_df[sanitized_ref] = df[sensor_name_ref].values

    merged_df.sort_values(by="time", inplace=True)
    merged_df.reset_index(drop=True, inplace=True)

    return merged_df

def load_dataframe_from_csv(load_path: Path = None) -> pd.DataFrame:

    load_path = Path(load_path)

    if load_path.suffix == "":
        load_path = load_path.with_suffix(".csv")
    elif load_path.suffix.lower() != ".csv":
        raise ValueError(f"Expected a .csv file, got '{load_path.suffix}' in path: {load_path}")

    return pd.read_csv(load_path)


def load_true_and_predicted_data_for_all_methods(calibration_method_dirs: Path) -> Dict[str, Dict[str, pd.DataFrame]]:

    all_data = {}

    for method_dir in calibration_method_dirs.iterdir():
        if method_dir.is_dir():
            method_name = method_dir.name
            method_data = {}
            for csv_file in method_dir.glob("*all_true_vs_pred.csv"):
                sensor_name = csv_file.stem.replace("_all_true_vs_pred", "")
                method_data[sensor_name] = pd.read_csv(csv_file)
            all_data[method_name] = method_data

    return all_data


def linear_regression_load_parameters(calibration_method_dir: Path) -> dict[str, float]:
    """
    Loads Linear Regression coefficients from .json file and returns dictionary of name and its value.
    """

    with open(calibration_method_dir, 'r') as f:
        data = json.load(f)

    coeffs: str = "coefficients"
    if coeffs not in data or not data[coeffs]:
        raise ValueError(f"JSON file does not contain {coeffs} list.")

    params = data[coeffs]

    required_keys = ["a", "b"]
    for key in required_keys:
        if key not in params:
            raise ValueError(f"Missing key '{key}' in {coeffs}")

    return params


def divided_linear_regression_load_parameters(
        calibration_method_dir: Path
) -> List[DatatypeCoefficientsForDividedLinearRegression]:
    """
    Loads Divided Linear Regression coefficients from .json file and returns list of
    DatatypeCoefficientsForDividedLinearRegression.
    """

    with open(calibration_method_dir, 'r') as f:
        data = json.load(f)

    coeffs: str = "coefficients"
    if coeffs not in data or not data[coeffs]:
        raise ValueError(f"JSON file does not contain {coeffs} list.")

    params = data[coeffs][:]

    required_keys = ["hour", "a", "b"]
    for idx, c in enumerate(data[coeffs]):
        for key in required_keys:
            if key not in c:
                raise ValueError(f"Missing key '{key}' in {coeffs} at index {idx}: {c}")

    return params


def polynominal_regression_load_parameters(calibration_method_dir: Path) -> dict[str, float]:
    """
    Loads Polynominal Regression coefficients from .json file and returns dictionary of name and its value.
    """

    with open(calibration_method_dir, 'r') as f:
        data = json.load(f)

    coeffs: str = "coefficients"
    if coeffs not in data or not data[coeffs]:
        raise ValueError(f"JSON file does not contain {coeffs} list.")

    params = data[coeffs]

    required_keys = ["a", "b", "c"]
    for key in required_keys:
        if key not in params:
            raise ValueError(f"Missing key '{key}' in {coeffs}")

    return params


def decision_tree_regression_load_parameters(calibration_method_dir: Path) -> dict[str, Any]:
    """
    Loads Decision Tree Regression coefficients from .json file and returns dictionary of name and its value (Any).
    """

    with open(calibration_method_dir, 'r') as f:
        data = json.load(f)

    coeffs: str = "coefficients"
    if coeffs not in data or not data[coeffs]:
        raise ValueError(f"JSON file does not contain {coeffs} list.")

    params = data[coeffs]

    if "params" not in params:
        raise ValueError(f"Missing 'params' key in {coeffs}")

        # Recursively validate the tree structure
    _validate_tree_structure(params["params"])

    return params["params"]


def mlp_load_parameters(calibration_method_dir: Path) -> DatatypeMLPRegressionParameters:
    """
    Loads Multi Layer Perceptron coefficients from .json file and returns the DatatypeMLPRegressionParameters.
    """

    with open(calibration_method_dir, 'r') as f:
        data = json.load(f)

    coeffs: str = "coefficients"
    if coeffs not in data or not data[coeffs]:
        raise ValueError(f"JSON file does not contain {coeffs} list.")

    coeff_params = data.get(coeffs)

    required_keys = ["layer_1_weights", "layer_1_biases", "layer_2_weights", "layer_2_biases", "output_weights", "output_biases"]
    for key in required_keys:
        if key not in coeff_params:
            raise ValueError(f"Missing key '{key}' in {coeffs}")

    scalers: str = "scalers"
    if scalers not in data or not data[scalers]:
        raise ValueError(f"JSON file does not contain {scalers} list.")

    scaler_params = data.get(scalers)

    required_keys = ["x_scaler_mean", "x_scaler_scale", "y_scaler_mean", "y_scaler_scale", "activation"]
    for key in required_keys:
        if key not in scaler_params:
            raise ValueError(f"Missing key '{key}' in {scalers}")

    params: DatatypeMLPRegressionParameters = {
        "coefficients": coeff_params,
        "scalers": scaler_params
    }

    return params


def load_str_dict_from_csv(load_path: Path = None) -> dict[str, str]:

    load_path = Path(load_path)

    if load_path.suffix == "":
        load_path = load_path.with_suffix(".csv")
    elif load_path.suffix.lower() != ".csv":
        raise ValueError(f"Expected a .csv file, got '{load_path.suffix}' in path: {load_path}")

    with load_path.open(mode='r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        result = {row['key']: row['value'] for row in reader}

    return result

import pandas as pd
import json
import csv
import logging

from pathlib import Path
from matplotlib.figure import Figure
from typing import Optional, Any

from pvtools.config.sensor_calibration_metrics import SensorCalibrationMetrics

required_metric_fields = ["mse", "mae", "rmse", "r2", "mape", "max_error", "bias"]

log = logging.getLogger(__name__)


def save_metrics_to_json(
        metrics: SensorCalibrationMetrics,
        samples_count: int,
        coefficients_list: Any = None,
        filename_path: Path = None,
        scalers_list: list[dict] = None
) -> None:

    for attr in required_metric_fields:
        if not hasattr(metrics, attr):
            raise TypeError(f"metrics must have '{attr}' attribute")

    if not isinstance(samples_count, int):
        raise TypeError("samples_count must be an int")

    metrics_json = {
        "mse": float(metrics.mse),
        "mae": float(metrics.mae),
        "rmse": float(metrics.rmse),
        "r2": float(metrics.r2),
        "mape": float(metrics.mape),
        "max_error": float(metrics.max_error),
        "bias": float(metrics.bias),
        "n_samples": samples_count,
    }

    if coefficients_list is not None:
        metrics_json["coefficients"] = coefficients_list

    if scalers_list is not None:
        metrics_json["scalers"] = scalers_list

    if filename_path is not None:
        filename_path.parent.mkdir(parents=True, exist_ok=True)

        with open(filename_path, "w") as f:
            json.dump(metrics_json, f, indent=2)


def save_true_and_predicted_data_to_csv(
        y_pred: pd.Series,
        output_path: Path,
        y_true: pd.Series = None,
        index: pd.Series = None,
        time: pd.Series = None
) -> None:

    if y_true is not None:
        columns = pd.DataFrame({"y_true": y_true, "y_pred": y_pred})
    else:
        columns = pd.DataFrame({"y_pred": y_pred})

    if index is not None:
        columns["index"] = index # NOTE: index added on purpose, need for identyfing test/train split!
    if time is not None:
        columns["time"] = time

    output_path.parent.mkdir(parents=True, exist_ok=True)

    if index is None and time is None:
        columns.to_csv(output_path, index=True)
    else:
        columns.to_csv(output_path, index=False)


def save_dataframe_to_csv(
        df: pd.DataFrame,
        output_path: Path,
        index: Optional[bool] = False,
        index_label: Optional[str] = None
) -> None:

    if output_path is not None:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        df.to_csv(
            output_path,
            index=index,
            index_label=index_label
        )


def save_figure(
        fig: Figure,
        save_dir: Path=None,
        filename: str=None,
) -> None:

    if save_dir is not None:
        save_dir = Path(save_dir)
        save_dir.mkdir(parents=True, exist_ok=True)
        output_path = save_dir / filename

    log.debug(f"Saving: {output_path}")
    try:
        fig.savefig(output_path, dpi=300)
        log.info(f"Success saved: {output_path}")
    except Exception as e:
        log.error(f"Failed to save {output_path}: {e}")


def save_predicted_data_figures(
        figures: list[tuple[str, str, Figure]],
        save_dir: Path=None,
) -> None:

    log.info(f"Saving figures to: {save_dir} (type: {type(save_dir)})")

    save_dir = Path(save_dir)
    save_dir.mkdir(parents=True, exist_ok=True)

    for sensor_name, calibration_method, fig in figures:
        save_figure(fig, save_dir, f"{sensor_name}.png")


def save_str_dict_to_csv(
        dict_: dict[str, str],
        output_path: Path
) -> None:

    if output_path is not None:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with output_path.open(mode='w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['key', 'value'])
            for key, value in dict_.items():
                writer.writerow([key, value])

import pandas as pd
from pathlib import Path
from pvtools.io_file.writer import save_dataframe_to_csv
def limit_sensor_ref_irradiance_to_clear_sky_model( df: pd.DataFrame, clearsky_df: pd.DataFrame, sensor_name_ref: str = 'irr_dav_1', poa_global_name: str = 'poa_global', save_dir: Path = None, filename: str = None ) -> pd.DataFrame:
if not isinstance(df, pd.DataFrame) or not isinstance(clearsky_df, pd.DataFrame): raise TypeError("Expected 'df' and 'clear_sky_df' to be a pandas DataFrame")
if 'time' not in df.columns or 'time' not in clearsky_df.columns: raise ValueError("'time' column needs to be provided!")
mismatched_times = set(df['time']) - set(clearsky_df['time']) if mismatched_times: raise ValueError("Timestamps are mismatched!")
df = df.copy()
merged = (df[['time', sensor_name_ref]].merge(clearsky_df[['time', poa_global_name]], on='time', how='inner'))
limited_df = merged.copy() limited_df[sensor_name_ref] = limited_df[sensor_name_ref].clip(upper=limited_df[poa_global_name])
df[sensor_name_ref] = limited_df[sensor_name_ref]
if save_dir is not None: save_dir = Path(save_dir) output_path = save_dir / "filtered" / f"{filename}.csv" save_dataframe_to_csv(df, output_path, index=False)
return df
def limit_sensors_irradiance_to_clear_sky_model( df: pd.DataFrame, clearsky_df: pd.DataFrame, sensor_names: list[str] = None, poa_global_name: str = 'poa_global' ) -> pd.DataFrame:
if not isinstance(df, pd.DataFrame) or not isinstance(clearsky_df, pd.DataFrame): raise TypeError("Expected 'df' and 'clear_sky_df' to be a pandas DataFrame")
if 'time' not in df.columns or 'time' not in clearsky_df.columns: raise ValueError("'time' column needs to be provided!")
if not (df["time"] == clearsky_df["time"]).all(): raise ValueError("Timestamps are mismatched!")
df = df.copy() clearsky_df["time"] = pd.to_datetime(clearsky_df["time"])
merged = (df[['time', *sensor_names]].merge(clearsky_df[['time', poa_global_name]], on='time', how='inner', sort=False))
limited = merged.copy() limited[sensor_names] = merged[sensor_names].clip(upper=merged[poa_global_name], axis='index')
df.loc[:, sensor_names] = limited[sensor_names]
return df
def remove_negative_measurements(df: pd.DataFrame) -> pd.DataFrame: if not isinstance(df, pd.DataFrame): raise TypeError("Expected 'df' to be a pandas DataFrame")
df = df.copy()
for col in df.columns: if col == 'time': continue df[col] = df[col].clip(lower=0)
return df

import matplotlib.pyplot as plt import numpy as np import pandas as pd
from typing import Optional from pathlib import Path from matplotlib.axes import Axes from matplotlib.figure import Figure
from pvtools.io_file.writer import save_figure
def plot_from_dataframe( df: pd.DataFrame, save_dir: Path = None, filename: str = None, sensor_names: list[str] = None, sensor_name_ref: str = None, show: bool = True, title: str = "Plot" ) -> tuple[Figure, Axes]: """ Plot raw sensor data and optionally, if sensor reference is provided it's values on the same graph. """
if sensor_names is None: raise ValueError("Parameter 'sensor_names' must be a list of column names.")
df = df.copy() if 'time' in df.columns: df['time'] = pd.to_datetime(df['time'], errors='coerce') x = df['time'] else: x = pd.to_datetime(df.index, errors='coerce')
# Plot 1: Raw input series over time fig, ax = plt.subplots(figsize=(9, 4))
if sensor_name_ref is not None: ax.plot(x, df[sensor_name_ref], label="Power Reference (actual)", linewidth=0.9)
for sensor_col in sensor_names: ax.plot(x, df[sensor_col], label=f"Sensor: {sensor_col}", linewidth=0.9) ax.set_title(title) ax.set_xlabel("Time") ax.set_ylabel("Power (W/m²)") ax.legend( loc="upper right", fontsize=5 ) ax.grid(True) fig.tight_layout()
if show: fig.show()
if save_dir is not None: save_figure(fig, save_dir, filename)
return fig, ax
def subplot_predicted_data( data: dict[str, pd.DataFrame], y_true: str, y_pred: str, calibration_method: str, ) -> list[tuple[str, str, Figure]]:
figures = []
for sensor_name, df in data.items(): fig, ax = plt.subplots(figsize=(9, 4)) ax.plot( data[sensor_name].index, data[sensor_name][y_true], label=y_true, linewidth=0.9)
ax.plot( data[sensor_name].index, data[sensor_name][y_pred], label=y_pred, linewidth=0.9)
ax.set_title(f"{sensor_name} prediciton by {calibration_method}") ax.set_xlabel("Samples") ax.set_ylabel("Power (W/m²)") ax.legend() ax.grid(True) fig.tight_layout()
figures.append((sensor_name, calibration_method, fig))
return figures
def plot_clear_sky( cs: pd.DataFrame, save_dir: Optional[Path] = None, show: bool = True, ) -> Figure: """ Plots clear sky irradiance DHI, GHI, DHI [W/m²] """
fig, ax = plt.subplots(figsize=(10, 4)) cs.plot(ax=ax) ax.set_ylabel("Irradiance (W/m²)") ax.set_title("Clear‐sky irradiance (DNI, GHI, DHI)") ax.grid(True) ax.legend( title="", loc="upper right", fontsize=5 ) fig.tight_layout()
save_figure(fig, save_dir, "clear_sky_model.png")
if show: fig.show() return fig
def plot_poa_components( poa: pd.DataFrame, save_dir: Optional[Path] = None, show: bool = True, ) -> Figure: """ Plots Plane-Of-Array irradiance in [W/m²]:
* ``poa global`` * ``poa direct`` * ``poa diffuse`` * ``poa ground diffuse`` """
fig, ax = plt.subplots(figsize=(10, 4)) poa[['poa_global', 'poa_direct', 'poa_diffuse', 'poa_ground_diffuse']].plot(ax=ax) ax.set_ylabel("Irradiance (W/m²)") ax.set_title("Plane‐of‐Array Irradiance (Perez model)") ax.legend( title="", loc="upper right", fontsize=5 ) ax.grid(True) fig.tight_layout()
save_figure(fig, save_dir, "poa_components.png")
if show: fig.show() return fig
def plot_poa_vs_reference( poa_global: pd.Series, sensor_reference: pd.Series, save_dir: Optional[Path] = None, show: bool = True, ) -> Figure: """ Plots Plane-Of-Array and reference sensor irradiance in [W/m²]. """
if len(poa_global) == len(sensor_reference): sensor_copy = sensor_reference.copy() sensor_copy.index = poa_global.index else: raise ValueError("Incorret number of rows")
df = pd.concat({"POA Global": poa_global, "Reference": sensor_copy}, axis=1)
fig, ax = plt.subplots(figsize=(10, 4)) df.plot(ax=ax, linewidth=0.9) ax.set_ylabel("Irradiance / Power (W/m²)") ax.set_title("POA Global vs Sensor Reference") ax.legend( title="", loc="upper right", fontsize=5 ) ax.grid(True) fig.tight_layout()
if save_dir is not None: save_figure(fig, save_dir, "poa_vs_reference.png")
if show: fig.show()
return fig
def plot_poa_reference_with_clearsky_periods( poa_global: pd.DataFrame, sensor_reference: pd.DataFrame, sunny: pd.Series, save_dir: Optional[Path] = None, show: bool = True ) -> Figure: """ Plots Plane-Of-Array and reference sensor irradiance with marked detected sunny periods [W/m²]. """
poa_global = poa_global.copy() sensor_reference = sensor_reference.copy() sunny = sunny.copy()
poa_global = poa_global.set_index("time") sensor_reference = sensor_reference.set_index("time")
fig = plot_poa_vs_reference( poa_global=poa_global, sensor_reference=sensor_reference, save_dir=None, show=False )
ax = fig.axes[0] ax.scatter( sunny.index[sunny], sensor_reference[sunny], s=12, zorder=5, label="Clear-sky samples" )
ax.set_title("POA Global vs Sensor Reference (clear-sky highlighted)") ax.legend(title="") ax.legend( loc="upper right", fontsize=5 ) fig.tight_layout()
if save_dir is not None: save_figure(fig, save_dir, "poa_vs_reference_sunny.png")
if show: fig.show()
return fig
def plot_sensors_calibrated_directly_to_poa( result_df: pd.DataFrame, title: str = "default plot", save_dir: Optional[Path] = None, filename: str = "default_filename", show: bool = False, ) -> None: """ Plots Plane-Of-Array, reference sensor and basic sensors directly calibrated to POA irradiance [W/m²]. """
