# highlight clear-sky clear_idx = result_df.index[result_df["clearsky_mask"]] ax.scatter(clear_idx, result_df.loc[clear_idx, "sensor"], s=5, color="green", label="Clear-sky detected")
ax.set_title(title) ax.set_ylabel("Irradiance W/m²") ax.set_xlabel("Time") ax.legend() ax.grid() plt.tight_layout()
