def plot_frequency_histogram( freqs, fft_mag, bins=100, title: str = "Frequency Histogram of Irradiance Signal", save_dir: Optional[Path] = None, filename: str = "default_filename", show: bool = False, ) -> None: """ Plots frequency histrogram. """
fig, ax = plt.figure(figsize=(12, 5))
fig.hist(freqs, weights=fft_mag, bins=bins, edgecolor='black') fig.xlabel("Frequency (Hz)") fig.ylabel("Magnitude (sum of FFT power)") fig.title(title) fig.grid()
if save_dir is not None: save_figure(fig, save_dir, f"{filename}.png")
