def plot_fft_spectrum( freqs, fft_mag, max_freq=None, title: str = "Frequency Spectrum (FFT)", save_dir: Optional[Path] = None, filename: str = "default_filename", show: bool = False, ) -> None:
fig, ax = plt.figure(figsize=(12, 5))
if max_freq: mask = freqs <= max_freq fig.plot(freqs[mask], fft_mag[mask]) else: fig.plot(freqs, fft_mag)
fig.xlabel("Frequency (Hz)") fig.ylabel("Magnitude") fig.title(title) fig.grid()
